/**
 * Seeded by gate-self-test to prove the coverage ratchet can go red.
 *
 * Nothing imports this file, so with `coverage.all` every line below counts as
 * uncovered and drags the totals under the committed baseline. If the ratchet
 * still passes with this present, it is not reading what it claims to read.
 */
export function seededUncoveredA(input: number): number {
  if (input > 10) {
    return input * 2
  }
  if (input > 5) {
    return input + 1
  }
  return 0
}

export function seededUncoveredB(values: string[]): string {
  const out: string[] = []
  for (const value of values) {
    if (value.length > 3) {
      out.push(value.toUpperCase())
    } else {
      out.push(value.toLowerCase())
    }
  }
  return out.join(',')
}

export function seededUncoveredC(flag: boolean): string {
  if (flag) {
    return 'yes'
  }
  return 'no'
}
